    /**
     * Set to true if your date columns are NOT NULL and you need to keep
     * the literal '0000-00-00' values from the original dump.
     * (MySQL strict mode usually rejects '0000-00-00'.)
     */
    private const KEEP_ZERO_DATES = false;

    private const COLUMNS = [
        'ee_profile', 'ee_firstname', 'ee_middlename', 'ee_lastname', 'ee_gender',
        'ee_birth_date', 'ee_civil_status', 'ee_email', 'ee_mobile_number', 'ee_telephone',
        'ee_sss', 'ee_tinid', 'ee_bloodtype', 'ee_ecname', 'ee_eccontact', 'ee_ecaddress',
        'ee_company_reference', 'ee_center_reference', 'ee_department_reference',
        'ee_position_reference', 'ee_position_level_reference', 'ee_job_family',
        'ee_employment_status', 'ee_id_number', 'ee_id_biometrics', 'ee_date_hired',
        'ee_date_hired_tdg', 'ee_date_contractual_start', 'ee_date_contractual_end',
        'ee_status', 'ee_created_by', 'ee_created_at', 'ee_updated_at',
    ];

    private const DATE_COLUMNS = [
        'ee_date_hired', 'ee_date_hired_tdg',
        'ee_date_contractual_start', 'ee_date_contractual_end',
    ];

    public function run(): void
    {
        $rows = array_map(function (array $row) {
            $record = array_combine(self::COLUMNS, $row);

            if (! self::KEEP_ZERO_DATES) {
                foreach (self::DATE_COLUMNS as $col) {
                    if ($record[$col] === '0000-00-00') {
                        $record[$col] = null;
                    }
                }
            }

            return $record;
        }, $this->data());

        // Fresh seed: uncomment the next line to wipe the table first.
        // DB::table('employees')->truncate();

        foreach (array_chunk($rows, 50) as $chunk) {
            DB::table('employees')->insert($chunk);
        }
    }

